window.fetch=denied('fetch');window.WebSocket=class{constructor(){denied('WebSocket')()}};window.EventSource=class{constructor(){denied('EventSource')()}};window.XMLHttpRequest=class{constructor(){denied('XHR')()}};navigator.sendBeacon=denied('sendBeacon');window.open=denied('window.open');
