window.auditGeometry=()=>{const r=s=>document.querySelector(s).getBoundingClientRect().toJSON();return {viewport:innerWidth,height:innerHeight,dpr:devicePixelRatio,classes:document.body.className,runtime:r('#runtimeView'),shadowFrame:document.querySelector('#runtimeView').shadowRoot?.querySelector('iframe')?.getBoundingClientRect().toJSON(),hidden:document.hidden,panel:r('#browserSidebar'),panelStyle:{visibility:getComputedStyle(document.querySelector('#browserSidebar')).visibility,display:getComputedStyle(document.querySelector('#browserSidebar')).display},dockWidth:getComputedStyle(document.documentElement).getPropertyValue('--dsh-right-workspace-dock-width'),mode:harnessDesktopRightWorkspace.controller.getActiveModeId(),open:harnessDesktopRightWorkspace.controller.isOpen()}};
